INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2026128', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'A circle has the equation $x^2 + y^2 - 10x + 6y + 18 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Complete the square for both variables. Rearrange: $(x^2 - 10x) + (y^2 + 6y) = -18$. Complete the square: $(x^2 - 10x + 25) + (y^2 + 6y + 9) = -18 + 25 + 9$, giving $(x - 5)^2 + (y + 3)^2 = 16$. The standard form $(x - h)^2 + (y - k)^2 = r^2$ shows $r^2 = 16$, so $r = 4$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20XXNAR', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'The system of equations $6x - ky = 14$ and $9x + 12y = 21$ has infinitely many solutions. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$-8$"},{"key":"B","text":"$-18$"},{"key":"C","text":"$8$"},{"key":"D","text":"$18$"}]$lyceon_json$::jsonb, 'A', NULL, E'For infinitely many solutions, the two equations must be proportional: $\\frac{6}{9} = \\frac{-k}{12} = \\frac{14}{21}$. The ratio of the $x$-coefficients is $\\frac{6}{9} = \\frac{2}{3}$, and the ratio of the constants is $\\frac{14}{21} = \\frac{2}{3}$, confirming proportionality. Setting $\\frac{-k}{12} = \\frac{2}{3}$ gives $-k = \\frac{2 \\cdot 12}{3} = 8$, so $k = -8$. The value $-18$ comes from incorrectly cross-multiplying as $k = -\\frac{6 \\cdot 12}{9 \\cdot \\frac{2}{3}}$ or a similar setup error producing $-18$. The value $8$ results from dropping the negative sign when solving $-k = 8$ (sign error). The value $18$ comes from multiplying $\\frac{12 \\cdot 14}{21} \\cdot \\frac{3}{2}$ or confusing the proportionality condition with the determinant condition for no solutions (concept gap).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21M66IM', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'For $3x \\neq 2$, which expression is equivalent to $\\frac{6x^2 - 19x + 10}{3x - 2}$?', NULL, $lyceon_json$[{"key":"A","text":"$2x + 5$"},{"key":"B","text":"$2x - 5$"},{"key":"C","text":"$3x - 5$"},{"key":"D","text":"$2x - 10$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factor the numerator $6x^2 - 19x + 10$. We need two numbers whose product is $6 \\times 10 = 60$ and whose sum is $-19$: those are $-4$ and $-15$. Rewriting: $6x^2 - 4x - 15x + 10 = 2x(3x - 2) - 5(3x - 2) = (2x - 5)(3x - 2)$. Dividing by $(3x - 2)$ gives $2x - 5$. The distractor $2x + 5$ results from a sign error when factoring out $-5$ from the second group. The distractor $3x - 5$ arises from incorrectly swapping coefficients during the grouping step, treating the factored form as $(3x - 5)(2x - 2)$. The distractor $2x - 10$ comes from dividing only the constant term $10$ by $1$ instead of properly canceling the common binomial factor.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21RG992', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'A circle in the $xy$-plane has center $(2, -7)$ and passes through the point $(5, -3)$. What is the slope of the line tangent to the circle at the point $(5, -3)$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{3}{4}$"},{"key":"B","text":"$\\frac{4}{3}$"},{"key":"C","text":"$\\frac{3}{4}$"},{"key":"D","text":"$-\\frac{4}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of the radius from the center $(2, -7)$ to the point $(5, -3)$ is $\\frac{-3 - (-7)}{5 - 2} = \\frac{4}{3}$. A tangent line is perpendicular to the radius at the point of tangency, so its slope is the negative reciprocal: $-\\frac{3}{4}$. The distractor $\\frac{4}{3}$ is the slope of the radius itself, confusing the radius with the tangent. The distractor $\\frac{3}{4}$ takes the reciprocal but forgets to negate, applying only half the perpendicularity condition. The distractor $-\\frac{4}{3}$ negates the radius slope without taking the reciprocal, again applying only half the negative-reciprocal rule.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21XNBSO', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $(5x - 3)(2x + 7)$?', NULL, $lyceon_json$[{"key":"A","text":"$10x^2 + 29x - 21$"},{"key":"B","text":"$10x^2 + 41x - 21$"},{"key":"C","text":"$10x^2 + 29x + 21$"},{"key":"D","text":"$10x^2 - 29x - 21$"}]$lyceon_json$::jsonb, 'A', NULL, E'Applying the distributive property (FOIL): $(5x - 3)(2x + 7) = 5x \\cdot 2x + 5x \\cdot 7 + (-3) \\cdot 2x + (-3) \\cdot 7 = 10x^2 + 35x - 6x - 21 = 10x^2 + 29x - 21$. The distractor $10x^2 + 41x - 21$ results from adding the cross terms $35 + 6 = 41$ instead of $35 - 6 = 29$. The distractor $10x^2 + 29x + 21$ has the correct middle term but incorrectly makes the constant positive, losing the negative sign from $(-3)(7)$. The distractor $10x^2 - 29x - 21$ incorrectly negates the entire middle term.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22NJCYU', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'What value of $x$ satisfies the equation $$\\frac{2x + 9}{3} = \\frac{5x - 1}{7}\\,?$$', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '66', ARRAY['66'], E'Cross-multiplying gives $7(2x + 9) = 3(5x - 1)$. Expanding: $14x + 63 = 15x - 3$. Subtracting $14x$ from both sides yields $63 = x - 3$. Adding $3$ to both sides gives $x = 66$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23NSU12', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'What is the $x$-coordinate of the $x$-intercept of the line that passes through the points $(2, 9)$ and $(6, -3)$?', NULL, $lyceon_json$[{"key":"A","text":"$-1$"},{"key":"B","text":"$1$"},{"key":"C","text":"$3$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'D', NULL, E'The slope is $\\frac{-3 - 9}{6 - 2} = \\frac{-12}{4} = -3$. Using point-slope form with $(2, 9)$: $y - 9 = -3(x - 2)$, which simplifies to $y = -3x + 15$. Setting $y = 0$: $0 = -3x + 15$, so $x = 5$. The value $-1$ results from reversing the order of subtraction in the denominator of the slope (computing $\\frac{12}{-4} \\cdot (-1)$ erroneously as slope $3$), getting $y = 3x + 3$, and then solving $0 = 3x + 3$ to obtain $x = -1$. The value $1$ results from a sign error when computing $b$: using $9 = -3(2) + b$ but writing $9 = 6 + b$ instead of $9 = -6 + b$, giving $b = 3$ and the equation $y = -3x + 3$, so $x = 1$. The value $3$ results from confusing the $y$-intercept value $b = 3$ (from the sign error) with the $x$-intercept itself.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24RD2FL', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'What is the sum of the solutions to the equation $2x^2 - 13x + 21 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13/2', ARRAY['13/2', '6.5'], E'Factor the quadratic: we need two numbers whose product is $2 \\times 21 = 42$ and whose sum is $-13$. Those are $-6$ and $-7$. Rewriting: $2x^2 - 6x - 7x + 21 = 2x(x - 3) - 7(x - 3) = (2x - 7)(x - 3) = 0$. The solutions are $x = \\frac{7}{2}$ and $x = 3$. Their sum is $\\frac{7}{2} + 3 = \\frac{7}{2} + \\frac{6}{2} = \\frac{13}{2}$. Alternatively, by Vieta''s formulas, the sum of the roots of $2x^2 - 13x + 21 = 0$ is $\\frac{13}{2}$. A common error is forgetting to divide by the leading coefficient and reporting the sum as $13$. Another error is computing the product of the roots ($\\frac{21}{2}$) instead of the sum.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24VDCSI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A car travels $217$ miles using $7$ gallons of fuel. A truck travels $312$ miles using $13$ gallons of fuel. How many more miles per gallon does the car get compared to the truck?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$7$"},{"key":"C","text":"$9$"},{"key":"D","text":"$24$"}]$lyceon_json$::jsonb, 'B', NULL, E'The car''s fuel efficiency is $217 \\div 7 = 31$ miles per gallon. The truck''s fuel efficiency is $312 \\div 13 = 24$ miles per gallon. The difference is $31 - 24 = 7$ miles per gallon. The value $3$ results from computing $312 \\div 13$ incorrectly as $28$, giving $31 - 28 = 3$. The value $9$ results from computing $217 \\div 7$ incorrectly as $33$, giving $33 - 24 = 9$. The value $24$ is the truck''s fuel efficiency alone, without computing the difference — an incomplete answer.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM254D6QW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A wildlife biologist tags 83 birds at a nature reserve: 29 are finches, 37 are warblers, and 17 are thrushes. If one bird is selected at random from the tagged group, what is the probability that it is a warbler?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{29}{83}$"},{"key":"B","text":"$\\frac{37}{83}$"},{"key":"C","text":"$\\frac{17}{83}$"},{"key":"D","text":"$\\frac{37}{46}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The probability of selecting a warbler is the number of warblers divided by the total number of birds: $\\frac{37}{83}$. The value $\\frac{29}{83}$ results from selecting the finch count instead of the warbler count. The value $\\frac{17}{83}$ results from selecting the thrush count. The value $\\frac{37}{46}$ results from dividing warblers by the sum of the other two groups ($29 + 17 = 46$) rather than the total, a fundamental misunderstanding of the probability formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25WC1XO', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $11$ inches. What is the circumference of the circle, in inches?', NULL, $lyceon_json$[{"key":"A","text":"$11\\pi$"},{"key":"B","text":"$22\\pi$"},{"key":"C","text":"$121\\pi$"},{"key":"D","text":"$44\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is $C = 2\\pi r = 2\\pi(11) = 22\\pi$ inches. The distractor $11\\pi$ uses $\\pi r$ instead of $2\\pi r$, omitting the factor of $2$. The distractor $121\\pi$ computes the area formula $\\pi r^2 = \\pi(11)^2 = 121\\pi$ instead of the circumference. The distractor $44\\pi$ computes $4\\pi r = 4\\pi(11) = 44\\pi$, doubling the correct circumference by using $4$ instead of $2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2606GL8', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the value of $x$ in the solution to the system of equations?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2622KXX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A factory packages 168 items into 12 identical boxes, with the same number of items in each box. At this rate, how many items would be packaged into 23 boxes?', NULL, $lyceon_json$[{"key":"A","text":"$276$"},{"key":"B","text":"$299$"},{"key":"C","text":"$322$"},{"key":"D","text":"$345$"}]$lyceon_json$::jsonb, 'C', NULL, E'Each box contains $168 \\div 12 = 14$ items. For 23 boxes: $14 \\times 23 = 322$. The value $276$ results from multiplying $12 \\times 23 = 276$, using the number of boxes rather than the items per box. The value $299$ results from computing $168 \\div 12$ as $13$ (an arithmetic error) and then $13 \\times 23 = 299$. The value $345$ results from computing $168 \\div 12$ as $15$ and then $15 \\times 23 = 345$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26FHB9T', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A store bought a shipment of $240$ shirts for $\\$18$ each. The store sold $75\\%$ of the shirts at $\\$31$ each and the remaining shirts at $\\$14$ each. What was the store''s total profit on the shipment?', NULL, $lyceon_json$[{"key":"A","text":"$\\$1{,}260$"},{"key":"B","text":"$\\$2{,}100$"},{"key":"C","text":"$\\$3{,}120$"},{"key":"D","text":"$\\$6{,}420$"}]$lyceon_json$::jsonb, 'B', NULL, E'Total cost is $240 \\times 18 = 4{,}320$ dollars. The store sold $75\\%$ of $240 = 180$ shirts at $\\$31$ each for revenue of $180 \\times 31 = 5{,}580$ dollars. The remaining $60$ shirts were sold at $\\$14$ each for revenue of $60 \\times 14 = 840$ dollars. Total revenue is $5{,}580 + 840 = 6{,}420$ dollars. Profit is $6{,}420 - 4{,}320 = 2{,}100$ dollars. The value $\\$1{,}260$ comes from computing only the full-price revenue minus cost: $5{,}580 - 4{,}320 = 1{,}260$, ignoring the discounted shirts entirely. The value $\\$3{,}120$ results from assuming all $240$ shirts sold at $\\$31$: $240 \\times (31 - 18) = 240 \\times 13 = 3{,}120$. The value $\\$6{,}420$ is the total revenue without subtracting the purchase cost.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26ZCZTG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the relationship between the number of fertilizer applications, $x$, and crop yield in bushels per acre, $y$, and determines the line of best fit to be $y = 4.7x + 31.2$. Which of the following is the best interpretation of the slope of this line?', NULL, $lyceon_json$[{"key":"A","text":"For each additional fertilizer application, the predicted crop yield increases by $31.2$ bushels per acre."},{"key":"B","text":"For each additional bushel per acre of crop yield, the number of fertilizer applications increases by $4.7$."},{"key":"C","text":"For each additional fertilizer application, the predicted crop yield increases by $4.7$ bushels per acre."},{"key":"D","text":"The predicted crop yield with no fertilizer applications is $4.7$ bushels per acre."}]$lyceon_json$::jsonb, 'C', NULL, E'The slope of the line of best fit, $4.7$, represents the predicted change in the dependent variable ($y$, crop yield) for each one-unit increase in the independent variable ($x$, fertilizer applications). So for each additional fertilizer application, the predicted crop yield increases by $4.7$ bushels per acre. The statement using $31.2$ confuses the slope with the $y$-intercept. The statement about the number of applications increasing by $4.7$ reverses the roles of the independent and dependent variables. The statement that the predicted yield with no applications is $4.7$ confuses the slope with the $y$-intercept value of $31.2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM277XVWN', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'From a point on level ground $83$ meters from the base of a tower, the angle of elevation to the top of the tower is $29°$. A vertical antenna sits on top of the tower. From the same point, the angle of elevation to the top of the antenna is $34°$. Which expression gives the height, in meters, of the antenna alone?', NULL, $lyceon_json$[{"key":"A","text":"$83(\\tan 34° - \\tan 29°)$"},{"key":"B","text":"$83(\\tan 29° - \\tan 34°)$"},{"key":"C","text":"$\\frac{83}{\\tan 34°} - \\frac{83}{\\tan 29°}$"},{"key":"D","text":"$83\\tan 34° + 83\\tan 29°$"}]$lyceon_json$::jsonb, 'A', NULL, E'The height to the top of the tower is $83\\tan 29°$ and the height to the top of the antenna is $83\\tan 34°$. The antenna height alone is the difference: $83\\tan 34° - 83\\tan 29° = 83(\\tan 34° - \\tan 29°)$. The distractor $83(\\tan 29° - \\tan 34°)$ reverses the subtraction order, producing a negative value. The distractor $\\frac{83}{\\tan 34°} - \\frac{83}{\\tan 29°}$ inverts the tangent relationship, confusing $\\tan\\theta = \\frac{\\text{opposite}}{\\text{adjacent}}$ with $\\frac{\\text{adjacent}}{\\text{opposite}}$. The distractor that adds the two terms treats the tower and antenna heights as separate quantities to combine rather than recognizing the antenna height is the difference.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27K9VRX', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two parallel lines are cut by a transversal. One of the alternate interior angles measures $53°$. What is the measure, in degrees, of the other alternate interior angle?', NULL, $lyceon_json$[{"key":"A","text":"$37°$"},{"key":"B","text":"$53°$"},{"key":"C","text":"$127°$"},{"key":"D","text":"$143°$"}]$lyceon_json$::jsonb, 'B', NULL, E'Alternate interior angles formed by two parallel lines and a transversal are congruent, so the other angle also measures $53°$. The distractor $37°$ results from subtracting $53$ from $90$, as if the angles were complementary rather than congruent. The distractor $127°$ comes from computing the supplement $180 - 53 = 127$, confusing alternate interior angles with co-interior (same-side interior) angles. The distractor $143°$ results from incorrectly computing $90 + 53 = 143$, conflating a right-angle offset with the angle relationship.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BDVMM9', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'Line $p$ passes through the point $(4, -1)$ and is perpendicular to the line $5x + 2y = 9$. What is the $y$-intercept of line $p$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-13/5', ARRAY['-13/5', '-2.6'], E'Rewriting $5x + 2y = 9$ in slope-intercept form gives $y = -\\frac{5}{2}x + \\frac{9}{2}$, so its slope is $-\\frac{5}{2}$. A line perpendicular to this has slope $\\frac{2}{5}$. Using point-slope form with $(4, -1)$: $y - (-1) = \\frac{2}{5}(x - 4)$, which gives $y + 1 = \\frac{2}{5}x - \\frac{8}{5}$. Solving for $y$: $y = \\frac{2}{5}x - \\frac{8}{5} - \\frac{5}{5} = \\frac{2}{5}x - \\frac{13}{5}$. The $y$-intercept is $-\\frac{13}{5}$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BTMCKE', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $7x - 4y = 28$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$4$"},{"key":"C","text":"$7$"},{"key":"D","text":"$28$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting $x = 0$ in $7x - 4y = 28$ gives $-4y = 28$, so $y = -7$. The $y$-intercept is $-7$. The value $4$ comes from finding the $x$-intercept instead: setting $y = 0$ gives $7x = 28$, so $x = 4$. The value $7$ results from dividing $28$ by $4$ but dropping the negative sign. The value $28$ comes from reading the constant on the right side of the equation without solving for $y$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C3VS9L', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A quality-control lab tests circuit boards from two production lines. Line P produces $61\\%$ of all boards and has a defect rate of $4\\%$. Line Q produces the remaining $39\\%$ and has a defect rate of $7\\%$. A board is selected at random from the combined output and is found to be defective. What is the probability, to the nearest thousandth, that it came from Line Q?', NULL, $lyceon_json$[{"key":"A","text":"$0.528$"},{"key":"B","text":"$0.472$"},{"key":"C","text":"$0.273$"},{"key":"D","text":"$0.070$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using Bayes'' theorem: $P(\\text{defective}) = (0.61)(0.04) + (0.39)(0.07) = 0.0244 + 0.0273 = 0.0517$. Then $P(Q \\mid \\text{defective}) = \\frac{(0.39)(0.07)}{0.0517} = \\frac{0.0273}{0.0517} \\approx 0.528$. The value $0.472$ is the complement, which results from computing $P(P \\mid \\text{defective})$ instead of $P(Q \\mid \\text{defective})$, effectively swapping the two lines. The value $0.273$ results from dividing $0.0273$ by $0.10$ (incorrectly adding the two defect rates $0.04 + 0.07 = 0.11$ rounded or miscomputed as $0.10$) instead of computing the weighted total probability correctly. The value $0.070$ simply states Line Q''s defect rate, ignoring the Bayesian update entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CH00NT', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $ABC$, $AB = AC$ and $\\angle BAC = 34°$. Point $D$ lies on side $AC$ such that $BD = BC$. What is the measure, in degrees, of $\\angle ADB$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '107', ARRAY['107'], E'Since triangle $ABC$ is isosceles with $AB = AC$ and $\\angle BAC = 34°$, the base angles are $\\angle ABC = \\angle ACB = \\frac{180 - 34}{2} = 73°$. In triangle $BDC$, we have $BD = BC$, so triangle $BDC$ is isosceles with $\\angle BDC = \\angle BCD$. Since $D$ lies on $AC$, $\\angle BCD = \\angle ACB = 73°$, so $\\angle BDC = 73°$. Then $\\angle DBC = 180 - 73 - 73 = 34°$. Now $\\angle ABD = \\angle ABC - \\angle DBC = 73 - 34 = 39°$. In triangle $ABD$: $\\angle BAD = 34°$, $\\angle ABD = 39°$, so $\\angle ADB = 180 - 34 - 39 = 107°$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D9J8FU', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A right circular cone has a height of $21$ cm and a base radius of $9$ cm. A plane parallel to the base cuts the cone at a height of $14$ cm from the base, creating a smaller cone above the cut. What is the volume, in cubic centimeters, of the smaller cone?', NULL, $lyceon_json$[{"key":"A","text":"$21\\pi$"},{"key":"B","text":"$63\\pi$"},{"key":"C","text":"$189\\pi$"},{"key":"D","text":"$7\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The smaller cone above the cut has height $21 - 14 = 7$ cm. By similar triangles, the ratio of the small cone''s dimensions to the full cone''s is $\\frac{7}{21} = \\frac{1}{3}$, so the small cone''s radius is $\\frac{1}{3}(9) = 3$ cm. The volume of the small cone is $\\frac{1}{3}\\pi(3)^2(7) = \\frac{1}{3}\\pi(9)(7) = 21\\pi$ cm$^3$. Alternatively, the full cone''s volume is $\\frac{1}{3}\\pi(9)^2(21) = 567\\pi$ cm$^3$, and volumes scale as the cube of the linear ratio: $567\\pi \\times \\left(\\frac{1}{3}\\right)^3 = \\frac{567\\pi}{27} = 21\\pi$. The distractor $63\\pi$ scales by the square of the ratio instead of the cube: $567\\pi \\times \\left(\\frac{1}{3}\\right)^2 = \\frac{567\\pi}{9} = 63\\pi$, treating the scaling as an area ratio rather than a volume ratio. The distractor $189\\pi$ scales by the linear ratio: $567\\pi \\times \\frac{1}{3} = 189\\pi$, dividing the volume by $3$ instead of $27$. The distractor $7\\pi$ omits squaring the radius in the cone formula, computing $\\frac{1}{3}\\pi(3)(7) = 7\\pi$ instead of $\\frac{1}{3}\\pi(3)^2(7) = 21\\pi$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EE7OKH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health researcher observes that patients who walk at least 8,000 steps per day have lower rates of high blood pressure than patients who walk fewer than 3,000 steps per day. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Walking at least 8,000 steps per day causes lower blood pressure."},{"key":"B","text":"There is an association between walking more steps per day and lower rates of high blood pressure."},{"key":"C","text":"Patients who walk fewer than 3,000 steps per day should be prescribed medication for high blood pressure."},{"key":"D","text":"The researcher's data proves that exercise is the primary factor in controlling blood pressure."}]$lyceon_json$::jsonb, 'B', NULL, E'Because this is an observational study (patients were not randomly assigned to step-count groups), the researcher can identify an association but cannot establish causation. Confounding variables such as overall fitness, diet, or age may explain the difference. Concluding that walking causes lower blood pressure inappropriately draws a causal inference from an observational design. Recommending medication goes beyond what the data support and introduces a treatment conclusion that the study did not test. Claiming the data proves exercise is the primary factor overstates the finding — observational data cannot prove a causal mechanism, and other factors were not controlled.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FDVR6R', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of $x$ satisfies the inequality $4x + 11 > 39$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$6$"},{"key":"C","text":"$7$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'D', NULL, E'Solving $4x + 11 > 39$: subtract $11$ from both sides to get $4x > 28$, then divide by $4$ to get $x > 7$. The value $8$ is the only option greater than $7$. The value $5$ gives $4(5) + 11 = 31$, which is not greater than $39$ (this results from miscomputing $39 - 11$ as $20$ and then $20 \\div 4 = 5$). The value $6$ gives $4(6) + 11 = 35$, also not greater than $39$ (this results from dividing $28$ by $4$ incorrectly as $6$). The value $7$ gives $4(7) + 11 = 39$, which equals $39$ but the inequality is strict ($>$, not $\\geq$), so $7$ does not satisfy it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FO6JUZ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f(x) = 2x^2 - 20x + 53$ can be rewritten in the form $f(x) = a(x - h)^2 + k$. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$28$"},{"key":"D","text":"$53$"}]$lyceon_json$::jsonb, 'A', NULL, E'Complete the square: $f(x) = 2x^2 - 20x + 53 = 2(x^2 - 10x) + 53$. Inside the parentheses, complete the square: $x^2 - 10x = (x - 5)^2 - 25$. Substituting back: $f(x) = 2[(x - 5)^2 - 25] + 53 = 2(x - 5)^2 - 50 + 53 = 2(x - 5)^2 + 3$. Therefore $k = 3$. The distractor $5$ gives the value of $h$ rather than $k$, confusing the vertex coordinates. The distractor $28$ results from failing to multiply the completed-square constant by the leading coefficient: computing $53 - 25 = 28$ instead of $53 - 2(25) = 3$. The distractor $53$ takes the original constant term without completing the square at all.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H0L3EB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of 400 college students at a large university and finds that 172 of them study more than 15 hours per week. The $95\\%$ confidence interval for the proportion of all students at the university who study more than 15 hours per week is $(0.39, 0.47)$. Which of the following statements is supported by this interval?', NULL, $lyceon_json$[{"key":"A","text":"At most $39\\%$ of all students at the university study more than 15 hours per week."},{"key":"B","text":"Exactly $43\\%$ of all students at the university study more than 15 hours per week."},{"key":"C","text":"It is plausible that $45\\%$ of all students at the university study more than 15 hours per week."},{"key":"D","text":"If the study were repeated with a sample of 100 students, the confidence interval would remain $(0.39, 0.47)$."}]$lyceon_json$::jsonb, 'C', NULL, E'The $95\\%$ confidence interval $(0.39, 0.47)$ means that all values within this interval are plausible values for the true population proportion. Since $0.45$ falls within $(0.39, 0.47)$, it is plausible that $45\\%$ of all students study more than 15 hours per week. Claiming at most $39\\%$ treats the lower bound as an upper limit, which reverses the meaning of the interval. Stating exactly $43\\%$ (the sample proportion $172/400 = 0.43$) treats the point estimate as the exact population parameter, ignoring the uncertainty captured by the interval. Claiming the interval would remain the same with a sample of 100 students ignores that a smaller sample produces a wider margin of error, so the interval would change.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HK6QER', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A delivery service charges a flat fee of $\\$13$ plus $\\$4$ per package. A customer has a budget of at most $\\$57$ for delivery. Which inequality represents the number of packages $p$ the customer can send, and what is the maximum number of packages?', NULL, $lyceon_json$[{"key":"A","text":"$13 + 4p \\leq 57$; at most $11$ packages"},{"key":"B","text":"$13 + 4p < 57$; at most $10$ packages"},{"key":"C","text":"$4 + 13p \\leq 57$; at most $4$ packages"},{"key":"D","text":"$13 + 4p \\leq 57$; at most $14$ packages"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is the flat fee $\\$13$ plus $\\$4$ per package, giving $13 + 4p \\leq 57$. Subtracting $13$: $4p \\leq 44$, so $p \\leq 11$. The maximum is $11$ packages. Using a strict inequality $13 + 4p < 57$ misreads "at most" as "less than" (concept gap), yielding $4p < 44$, $p < 11$, maximum $10$. Setting up the inequality as $4 + 13p \\leq 57$ reverses the roles of the flat fee and per-package rate (equation setup error), yielding $13p \\leq 53$, $p \\leq 4.08$, or at most $4$ packages. Dividing $\\frac{57}{4} = 14.25$ and rounding down to $14$ without first subtracting the flat fee (partial reasoning) gives the correct inequality but the wrong maximum.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I5H517', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What are the solutions to the equation $x^2 - 11x + 28 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = -4$ and $x = -7$"},{"key":"B","text":"$x = 4$ and $x = 7$"},{"key":"C","text":"$x = 2$ and $x = 14$"},{"key":"D","text":"$x = -4$ and $x = 7$"}]$lyceon_json$::jsonb, 'B', NULL, E'We need two numbers that multiply to $28$ and add to $-11$. Those numbers are $-4$ and $-7$, so the equation factors as $(x - 4)(x - 7) = 0$, giving $x = 4$ and $x = 7$. The distractor $x = -4$ and $x = -7$ results from confusing the signs: the factors contain $-4$ and $-7$, but setting each factor to zero gives positive solutions. The distractor $x = 2$ and $x = 14$ uses a pair that multiplies to $28$ but sums to $16$, not $11$. The distractor $x = -4$ and $x = 7$ mixes up signs on one factor, which does not produce a product of $28$ with the correct sum.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IWVM4U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A university researcher wants to test whether a new note-taking method improves exam scores. She recruits 120 volunteers and randomly assigns 60 to use the new method and 60 to use their usual method for an entire semester. At the end of the semester, the group using the new method scores an average of 6 points higher on the final exam. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The new note-taking method is likely to cause higher exam scores for all university students."},{"key":"B","text":"The new note-taking method likely caused the higher average exam score among the volunteers in this study."},{"key":"C","text":"There is an association between the new note-taking method and higher exam scores, but causation cannot be established."},{"key":"D","text":"The 6-point difference is too small to draw any conclusion from the study."}]$lyceon_json$::jsonb, 'B', NULL, E'Because participants were randomly assigned to treatment and control groups, this is a randomized experiment, which does support a causal conclusion. However, because the participants are volunteers rather than a random sample of all university students, the result can be generalized only to the volunteers in the study, not to all university students. Generalizing to all university students oversteps the scope since the sample was self-selected volunteers. Claiming causation cannot be established applies to observational studies, not to randomized experiments where random assignment controls for confounding variables. Dismissing the 6-point difference as too small to draw any conclusion ignores the experimental design; the magnitude of a meaningful difference depends on statistical significance, not an arbitrary threshold.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JFWZQC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally priced at $\\$130$ is on sale for $23\\%$ off. What is the sale price of the jacket?', NULL, $lyceon_json$[{"key":"A","text":"$\\$29.90$"},{"key":"B","text":"$\\$97.50$"},{"key":"C","text":"$\\$100.10$"},{"key":"D","text":"$\\$107.00$"}]$lyceon_json$::jsonb, 'C', NULL, E'The discount is $130 \\times 0.23 = 29.90$ dollars. The sale price is $130 - 29.90 = 100.10$ dollars. The value $\\$29.90$ is the discount amount itself, not the sale price — an incomplete answer. The value $\\$97.50$ results from computing $25\\%$ off instead of $23\\%$ off: $130 \\times 0.75 = 97.50$. The value $\\$107.00$ results from subtracting the percentage number directly from the price ($130 - 23 = 107$) rather than computing the actual percentage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K9IDFC', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A linear function $h$ satisfies $h(3) = 22$ and $h(11) = -2$. For what value of $x$ does $h(x) = 7$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{38}{3}$"},{"key":"B","text":"$-2$"},{"key":"C","text":"$7$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'D', NULL, E'The slope of $h$ is $\\frac{-2 - 22}{11 - 3} = \\frac{-24}{8} = -3$. Using $h(3) = 22$: $22 = -3(3) + b$, so $b = 31$ and $h(x) = -3x + 31$. Setting $h(x) = 7$: $7 = -3x + 31$, which gives $-3x = -24$ and $x = 8$. The value $-\\frac{38}{3}$ results from adding $7 + 31 = 38$ instead of subtracting, then dividing by $-3$. The value $-2$ results from computing the slope as positive $3$ (reversing the sign of the numerator), yielding $h(x) = 3x + 13$, and solving $3x + 13 = 7$ to get $x = -2$. The value $7$ comes from confusing the function output with the input, assuming that if $h(x) = 7$ then $x$ must also equal $7$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KJXXFJ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = (x + 11)^2 - 19$. What is the minimum value of $f(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-19$"},{"key":"B","text":"$19$"},{"key":"C","text":"$-11$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'A', NULL, E'The function $f(x) = (x + 11)^2 - 19$ is in vertex form $a(x - h)^2 + k$ with $a = 1 > 0$, so the parabola opens upward and has a minimum at the vertex. The minimum value is $k = -19$, occurring when $(x + 11)^2 = 0$, i.e., at $x = -11$. The distractor $19$ results from dropping the negative sign on the constant term. The distractor $-11$ confuses the $x$-coordinate of the vertex with the minimum value of the function. The distractor $11$ takes the $x$-coordinate of the vertex and also drops its negative sign.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KWAESV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 250 residents of a city found that $58\\%$ favor expanding the public library. The margin of error for the survey is $\\pm 4$ percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $58\\%$ of all city residents favor expanding the library."},{"key":"B","text":"Between $54\\%$ and $62\\%$ of all city residents are likely to favor expanding the library."},{"key":"C","text":"Between $54\\%$ and $62\\%$ of the 250 residents surveyed favor expanding the library."},{"key":"D","text":"If the survey were repeated, exactly $58\\%$ would favor expanding the library each time."}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error defines a confidence interval around the sample proportion that is used to estimate the population parameter. Adding and subtracting 4 percentage points from $58\\%$ gives the interval $54\\%$ to $62\\%$, which is the plausible range for the true proportion of all city residents who favor expanding the library. Stating that exactly $58\\%$ of all residents favor it treats the sample statistic as the exact population parameter, ignoring sampling variability. Applying the interval to the 250 sampled residents confuses the population inference with the sample itself — the sample proportion is already known exactly. Claiming the result would be exactly $58\\%$ every time misunderstands sampling variability; repeated samples yield different proportions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M2ROLA', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'A movie theater sells adult tickets for $\\$11$ each and child tickets for $\\$7$ each. On a particular evening, the theater sold a total of $53$ tickets and collected $\\$475$ in ticket revenue. How many child tickets were sold?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '27', ARRAY['27'], E'Let $a$ represent the number of adult tickets and $c$ represent the number of child tickets. The system is $a + c = 53$ and $11a + 7c = 475$. From the first equation, $a = 53 - c$. Substituting into the second: $11(53 - c) + 7c = 475$, giving $583 - 11c + 7c = 475$, so $583 - 4c = 475$, thus $-4c = -108$ and $c = 27$. Verification: $a = 53 - 27 = 26$ adult tickets, revenue $= 11(26) + 7(27) = 286 + 189 = 475$. A common error is to report the number of adult tickets ($26$) instead of child tickets, or to set up $7a + 11c = 475$ (swapping the prices), which yields a different result.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M6WBPY', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'What value of $x$ satisfies the equation $8x - 23 = 49$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Adding $23$ to both sides gives $8x = 72$. Dividing both sides by $8$ yields $x = 9$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NZFA62', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h$ is defined by $h(x) = 3 \\cdot 2^x$. What is the value of $h(5)$?', NULL, $lyceon_json$[{"key":"A","text":"$30$"},{"key":"B","text":"$48$"},{"key":"C","text":"$96$"},{"key":"D","text":"$160$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 5$: $h(5) = 3 \\cdot 2^5 = 3 \\cdot 32 = 96$. The distractor $30$ results from treating the function as linear and computing $3 \\cdot 2 \\cdot 5 = 30$, misunderstanding exponential notation. The distractor $48$ comes from computing $3 \\cdot 2^4 = 3 \\cdot 16 = 48$, using the exponent $4$ instead of $5$. The distractor $160$ results from misreading the expression as $5 \\cdot 2^5 = 5 \\cdot 32 = 160$, replacing the coefficient $3$ with the input $5$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OB8NEW', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'What value of $x$ satisfies the equation $$5(2x - 3) - 4(x + 2) = 3(x - 7)\\,?$$', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{8}{3}$"},{"key":"B","text":"$\\frac{2}{3}$"},{"key":"C","text":"$2$"},{"key":"D","text":"$\\frac{16}{5}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Expanding the left side: $5(2x - 3) = 10x - 15$ and $-4(x + 2) = -4x - 8$, so the left side is $6x - 23$. The right side expands to $3x - 21$. Setting them equal: $6x - 23 = 3x - 21$, which simplifies to $3x = 2$, giving $x = \\frac{2}{3}$. The value $-\\frac{8}{3}$ results from failing to distribute the negative sign to the constant in the second term, computing $-4(x + 2)$ as $-4x + 2$ and obtaining $6x - 13 = 3x - 21$, hence $3x = -8$. The value $2$ results from not distributing the $5$ across the first parentheses, treating the left side as $(2x - 3) - 4(x + 2) = -2x - 11$, which leads to $-5x = -10$. The value $\\frac{16}{5}$ results from not distributing the $3$ on the right side, treating it as $x - 7$ instead of $3x - 21$, yielding $5x = 16$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OB8XAN', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, the side opposite a $31°$ angle has length $14$ and the hypotenuse has length $h$. Which equation can be used to find $h$?', NULL, $lyceon_json$[{"key":"A","text":"$\\sin(31°) = \\frac{14}{h}$"},{"key":"B","text":"$\\cos(31°) = \\frac{14}{h}$"},{"key":"C","text":"$\\tan(31°) = \\frac{14}{h}$"},{"key":"D","text":"$\\sin(31°) = \\frac{h}{14}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sine of an angle in a right triangle equals the ratio of the opposite side to the hypotenuse. Since $14$ is opposite the $31°$ angle and $h$ is the hypotenuse, $\\sin(31°) = \\frac{14}{h}$. The distractor using cosine confuses opposite with adjacent — cosine is adjacent over hypotenuse. The distractor using tangent incorrectly places the hypotenuse in the denominator — tangent is opposite over adjacent, not opposite over hypotenuse. The distractor $\\sin(31°) = \\frac{h}{14}$ inverts the fraction, placing the hypotenuse in the numerator instead of the denominator.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P559XM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are drawn from the same population of registered voters. Sample 1 has 600 voters and produces a $95\\%$ confidence interval of $(0.51, 0.59)$ for the proportion supporting a ballot measure. Sample 2 has 150 voters and produces a $95\\%$ confidence interval of $(0.44, 0.64)$. Which of the following best explains the difference between the two intervals?', NULL, $lyceon_json$[{"key":"A","text":"Sample 2 has a larger margin of error because its sample size is smaller, which increases variability in the sample proportion."},{"key":"B","text":"Sample 2's interval is wider because it was drawn from a different population than Sample 1."},{"key":"C","text":"Sample 1's interval is narrower because it has a higher confidence level than Sample 2."},{"key":"D","text":"The intervals differ because the two samples measured different proportions, proving the population proportion changed between surveys."}]$lyceon_json$::jsonb, 'A', NULL, E'The margin of error is inversely related to the square root of the sample size. Sample 1 ($n = 600$) has a margin of error of about $0.04$, while Sample 2 ($n = 150$) has a margin of error of about $0.10$. The smaller sample produces more variability in the sample proportion, leading to a wider confidence interval. The claim that the samples are from different populations contradicts the stated premise that both are drawn from the same population. The claim that Sample 1 has a higher confidence level is false — both intervals are stated to be $95\\%$ confidence intervals. The claim that the population proportion changed between surveys is unsupported; different sample proportions are expected due to sampling variability and do not prove a change in the true parameter.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PQF8NO', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'The function $h(x) = 189 - 9x$ models the amount of fuel, in liters, remaining in a storage tank after $x$ hours of continuous operation. What is the best interpretation of the number $9$ in this function?', NULL, $lyceon_json$[{"key":"A","text":"The tank uses $9$ liters of fuel per hour."},{"key":"B","text":"The tank contains $9$ liters of fuel at the start of operation."},{"key":"C","text":"The tank will be completely empty after $9$ hours."},{"key":"D","text":"The tank has been operating for $9$ hours."}]$lyceon_json$::jsonb, 'A', NULL, E'In $h(x) = 189 - 9x$, the coefficient $9$ multiplies $x$ (hours), so it represents the rate of fuel consumption: $9$ liters per hour. The initial amount is $189$ liters (the constant term when $x = 0$), not $9$, which eliminates the claim that $9$ is the starting amount. The tank empties when $189 - 9x = 0$, giving $x = 21$ hours, not $9$ hours. The variable $x$ represents hours elapsed, but $9$ is the rate coefficient, not a specific elapsed time.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PWOLCT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A teacher recorded the following test scores for $9$ students: $61, 67, 73, 74, 79, 83, 88, 91, 97$. What is the median test score?', NULL, $lyceon_json$[{"key":"A","text":"$74$"},{"key":"B","text":"$76.5$"},{"key":"C","text":"$79$"},{"key":"D","text":"$83$"}]$lyceon_json$::jsonb, 'C', NULL, E'With $9$ values already in ascending order, the median is the $\\frac{9+1}{2} = 5\\text{th}$ value, which is $79$. The value $74$ results from selecting the $4\\text{th}$ value instead of the $5\\text{th}$, a positional counting error. The value $76.5$ results from averaging the $4\\text{th}$ and $5\\text{th}$ values as $(74 + 79) \\div 2 = 76.5$, which is the procedure for an even number of data points, not an odd number. The value $83$ results from selecting the $6\\text{th}$ value, as if counting from the wrong end of the ordered list.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QBBJ8G', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'If $\\frac{x^4 - 16}{x^2 + 4} = ax^2 + b$ for all values of $x$ for which the expression is defined, what is the value of $a + b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-3', ARRAY['-3'], E'The numerator $x^4 - 16$ is a difference of squares: $x^4 - 16 = (x^2)^2 - 4^2 = (x^2 + 4)(x^2 - 4)$. Dividing by $(x^2 + 4)$ yields $x^2 - 4$. Matching with $ax^2 + b$, we get $a = 1$ and $b = -4$, so $a + b = 1 + (-4) = -3$. A common error is factoring incorrectly as $(x^2 + 4)(x^2 + 4)$, which would give $a + b = 1 + 4 = 5$. Another error is failing to recognize the difference of squares and instead attempting polynomial long division with an arithmetic slip, yielding $b = 4$ and $a + b = 5$. Students might also forget the negative sign on $b$ and report $a + b = 1 + 4 = 5$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QJB7B2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A line of best fit for a scatterplot is given by the equation $y = 3.1x + 8.9$, where $x$ represents the number of hours a student studied and $y$ represents the predicted test score. According to this model, what is the predicted test score for a student who studied for $7$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$21.7$"},{"key":"B","text":"$30.6$"},{"key":"C","text":"$40.6$"},{"key":"D","text":"$84.0$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 7$: $y = 3.1(7) + 8.9 = 21.7 + 8.9 = 30.6$. The value $21.7$ results from computing only the slope term $3.1 \\times 7 = 21.7$ without adding the $y$-intercept. The value $40.6$ results from misreading the $y$-intercept as $18.9$ instead of $8.9$: $21.7 + 18.9 = 40.6$. The value $84.0$ results from adding the slope and intercept first and then multiplying: $(3.1 + 8.9) \\times 7 = 12 \\times 7 = 84$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"graph_read_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QKAOYW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'A ladder leans against a vertical wall, making a $67°$ angle with the ground. The base of the ladder is $4.7$ feet from the wall. What is the length of the ladder, in feet, rounded to the nearest tenth?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '12.0', ARRAY['12'], E'Let $L$ be the length of the ladder (the hypotenuse). The distance from the base of the ladder to the wall ($4.7$ feet) is the adjacent side relative to the $67°$ angle. Using cosine: $\\cos(67°) = \\frac{4.7}{L}$, so $L = \\frac{4.7}{\\cos(67°)}$. Since $\\cos(67°) \\approx 0.3907$, $L \\approx \\frac{4.7}{0.3907} \\approx 12.03$, which rounds to $12.0$ feet.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RMUIEG', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'grid_in', E'The function $f$ is defined by $f(x) = 13x - 29$. What is the value of $f(4)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '23', ARRAY['23'], E'Substituting $x = 4$ into $f(x) = 13x - 29$ gives $f(4) = 13(4) - 29 = 52 - 29 = 23$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S7KLOA', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the exterior angle at vertex $R$ measures $139°$. If $\\angle P = (4x + 7)°$ and $\\angle Q = (3x - 2)°$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{36}{7}$"},{"key":"B","text":"$\\frac{134}{7}$"},{"key":"C","text":"$25$"},{"key":"D","text":"$41$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the Exterior Angle Theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles: $(4x + 7) + (3x - 2) = 139$, which simplifies to $7x + 5 = 139$, so $7x = 134$ and $x = \\frac{134}{7}$. The distractor $\\frac{36}{7}$ results from incorrectly using the interior angle at $R$ instead: setting $7x + 5 = 180 - 139 = 41$, yielding $7x = 36$. The distractor $25$ arises from dropping the constants and solving $7x = 175$ (using $175$ instead of $134$). The distractor $41$ is simply $180 - 139$, the interior angle at $R$, not the value of $x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TOP3BM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of 200 employees at a technology firm asked whether they commute by car or by train and whether they work in engineering or in sales. Of the 200 employees, 118 commute by car and 82 commute by train. Among those who commute by car, 71 work in engineering. Among those who commute by train, 53 work in sales. Given that a randomly selected employee works in sales, what is the probability that this employee commutes by train?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{53}{100}$"},{"key":"B","text":"$\\frac{53}{82}$"},{"key":"C","text":"$\\frac{53}{200}$"},{"key":"D","text":"$\\frac{82}{200}$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, determine the total number of sales employees. Car commuters in engineering: 71, so car commuters in sales: $118 - 71 = 47$. Train commuters in sales: 53, so train commuters in engineering: $82 - 53 = 29$. Total sales employees: $47 + 53 = 100$. The conditional probability that a sales employee commutes by train is $\\frac{53}{100}$. The value $\\frac{53}{82}$ divides by the total train commuters rather than the total sales employees, confusing P(train | sales) with P(sales | train). The value $\\frac{53}{200}$ divides by the grand total instead of conditioning on sales. The value $\\frac{82}{200}$ gives the unconditional probability of commuting by train, ignoring the sales condition entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TYLKEP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A rectangular garden has a length of $17$ feet and a width of $9$ feet. What is the area of the garden, in square feet?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '153', ARRAY['153'], E'The area of a rectangle is length times width: $A = 17 \\times 9 = 153$ square feet.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UJ76F2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'A town''s population increased by $15\\%$ from 2018 to 2020 and then decreased by $8\\%$ from 2020 to 2023. If the town''s population in 2023 was $10{,}580$, what was the population in 2018?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '10000', ARRAY['10000'], E'Let $P$ represent the 2018 population. After a $15\\%$ increase, the 2020 population is $1.15P$. After an $8\\%$ decrease from the 2020 value, the 2023 population is $1.15P \\times 0.92 = 1.058P$. Setting $1.058P = 10{,}580$ gives $P = 10{,}580 \\div 1.058 = 10{,}000$. A common error is to treat the overall change as $15\\% - 8\\% = 7\\%$ and compute $10{,}580 \\div 1.07 \\approx 9{,}888$, which incorrectly adds the percentage changes instead of multiplying the growth factors.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UQB64W', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A pharmaceutical company conducts a study in which 300 patients with chronic migraines at a single hospital are randomly assigned to receive either a new drug or a placebo. After 12 weeks, the group receiving the new drug reports $41\\%$ fewer migraine days on average than the placebo group. A medical journal reports: "The new drug has been proven to reduce migraines by $41\\%$ in the general population." Which of the following best identifies the flaw in the journal''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The study cannot establish causation because patients were not randomly assigned to groups."},{"key":"B","text":"The result can support a causal claim for the study participants, but generalizing to the entire general population is not justified because the sample was drawn from a single hospital."},{"key":"C","text":"The $41\\%$ reduction is not statistically meaningful because the study lasted only 12 weeks."},{"key":"D","text":"The placebo group invalidates the study because placebos have no medical purpose."}]$lyceon_json$::jsonb, 'B', NULL, E'The study uses random assignment, so a causal conclusion is supported for the study''s participants. However, because all 300 patients were drawn from a single hospital rather than randomly sampled from the general population, the result cannot be generalized beyond patients similar to those at that hospital. The journal''s claim that the drug is "proven" to work in the general population overstates the study''s external validity. Claiming the study cannot establish causation is incorrect because patients were randomly assigned to treatment and placebo groups, which is stated in the stem. Dismissing the result because the study lasted only 12 weeks applies an arbitrary duration threshold rather than evaluating the study''s design; a 12-week randomized trial can produce valid causal results. Claiming the placebo group invalidates the study misunderstands experimental design — placebos serve as the control condition necessary to isolate the effect of the drug.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UV53LE', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'What is the solution to the equation $\\sqrt{3x + 7} = x - 1$?', NULL, $lyceon_json$[{"key":"A","text":"$x = -1$ only"},{"key":"B","text":"$x = 3$"},{"key":"C","text":"$x = 6$ only"},{"key":"D","text":"$x = -1$ and $x = 6$"}]$lyceon_json$::jsonb, 'C', NULL, E'Squaring both sides: $3x + 7 = (x - 1)^2 = x^2 - 2x + 1$. Rearranging: $x^2 - 5x - 6 = 0$, which factors as $(x - 6)(x + 1) = 0$, giving $x = 6$ or $x = -1$. Checking $x = 6$: $\\sqrt{18 + 7} = \\sqrt{25} = 5$ and $6 - 1 = 5$. Valid. Checking $x = -1$: $\\sqrt{-3 + 7} = \\sqrt{4} = 2$ and $-1 - 1 = -2$. Since $2 \\neq -2$, this is extraneous. The only solution is $x = 6$. The distractor $x = -1$ only accepts the extraneous root and discards the valid one. The distractor $x = 3$ comes from a sign error when expanding $(x - 1)^2$ as $x^2 + 2x + 1$, leading to $x^2 - x - 6 = 0$ and solutions $x = 3$ or $x = -2$, then taking the positive root. The distractor listing both $x = -1$ and $x = 6$ fails to check for extraneous solutions after squaring.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WJK847', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylindrical water tank has a diameter of $6$ feet and a height of $11$ feet. What is the volume of the tank, in cubic feet?', NULL, $lyceon_json$[{"key":"A","text":"$99\\pi$"},{"key":"B","text":"$396\\pi$"},{"key":"C","text":"$66\\pi$"},{"key":"D","text":"$198\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The radius is half the diameter: $r = 3$ feet. The volume of a cylinder is $V = \\pi r^2 h = \\pi(3)^2(11) = 99\\pi$ cubic feet. The distractor $396\\pi$ uses the diameter instead of the radius: $\\pi(6)^2(11) = 396\\pi$. The distractor $66\\pi$ computes a lateral-surface-area-related quantity $2\\pi r h = 2\\pi(3)(11) = 66\\pi$ instead of the volume. The distractor $198\\pi$ doubles the correct volume, computing $2\\pi r^2 h = 2(99\\pi) = 198\\pi$ instead of $\\pi r^2 h$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WQ1WHR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A scatterplot shows the relationship between advertising spending (in thousands of dollars), $x$, and monthly revenue (in thousands of dollars), $y$, for $15$ stores. The line of best fit is $y = 1.9x + 43.5$. Store P has an advertising spending of $\\$22{,}000$ and a monthly revenue of $\\$97{,}000$. What is the residual for Store P, in thousands of dollars?', NULL, $lyceon_json$[{"key":"A","text":"$-11.7$"},{"key":"B","text":"$11.7$"},{"key":"C","text":"$53.5$"},{"key":"D","text":"$55.2$"}]$lyceon_json$::jsonb, 'B', NULL, E'The predicted revenue for $x = 22$ is $y = 1.9(22) + 43.5 = 41.8 + 43.5 = 85.3$ thousand dollars. The residual is the actual value minus the predicted value: $97 - 85.3 = 11.7$ thousand dollars. The value $-11.7$ results from computing the residual as predicted minus actual ($85.3 - 97$), reversing the correct order. The value $53.5$ results from subtracting only the intercept from the actual value: $97 - 43.5 = 53.5$, omitting the slope contribution. The value $55.2$ results from subtracting only the slope term from the actual value: $97 - 41.8 = 55.2$, omitting the intercept.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X293MV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'A data set of $11$ values has a mean of $37$. When the two largest values, $52$ and $58$, are removed, what is the mean of the remaining $9$ values?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '33', ARRAY['33'], E'The sum of all $11$ values is $11 \\times 37 = 407$. Removing the two largest values subtracts $52 + 58 = 110$ from the total, giving a remaining sum of $407 - 110 = 297$. The mean of the remaining $9$ values is $297 \\div 9 = 33$. A common error is to subtract only one value, such as computing $(407 - 58) \\div 10 = 34.9$, which removes only one value and divides by $10$ instead of $9$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XUOQ6B', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set contains the values: $14, 17, 19, 21, 23, 25, 27$. If the value $27$ is replaced by $83$, which of the following correctly describes the effect on the mean and median of the data set?', NULL, $lyceon_json$[{"key":"A","text":"Both the mean and the median increase."},{"key":"B","text":"The mean increases, but the median remains the same."},{"key":"C","text":"The median increases, but the mean remains the same."},{"key":"D","text":"Both the mean and the median remain the same."}]$lyceon_json$::jsonb, 'B', NULL, E'The original mean is $(14 + 17 + 19 + 21 + 23 + 25 + 27) \\div 7 = 146 \\div 7 \\approx 20.86$. After replacing $27$ with $83$, the new sum is $146 - 27 + 83 = 202$, and the new mean is $202 \\div 7 \\approx 28.86$, which is larger. The original median is the $4\\text{th}$ value, $21$. After the replacement, the ordered set is $14, 17, 19, 21, 23, 25, 83$, and the $4\\text{th}$ value is still $21$. Thus the mean increases while the median remains the same. Selecting both increase reflects a misunderstanding that extreme values always shift the median. Selecting that only the median changes, or that neither changes, reflects confusion about how the mean responds to a change in one data value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YF5MO1', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'In the $xy$-plane, a point $(a, b)$ lies in the solution region of the system of inequalities:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZHKQVE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A chemical solution requires mixing compound A and compound B in a ratio of $5{:}3$ by volume. A scientist has $1.4$ liters of compound A and $1.2$ liters of compound B. What is the maximum total volume of the solution, in liters, that the scientist can make while maintaining the required ratio?', NULL, $lyceon_json$[{"key":"A","text":"$2.00$"},{"key":"B","text":"$2.24$"},{"key":"C","text":"$2.60$"},{"key":"D","text":"$3.20$"}]$lyceon_json$::jsonb, 'B', NULL, E'In the $5{:}3$ ratio, for every $5$ parts of A there are $3$ parts of B, totaling $8$ parts. Check which compound is limiting. If all $1.4$ L of A is used, compound B needed is $1.4 \\times \\frac{3}{5} = 0.84$ L, which is less than the $1.2$ L available, so A is the limiting compound. The maximum solution is $1.4 + 0.84 = 2.24$ liters. The value $2.00$ comes from computing $1.2 \\times \\frac{5}{3} = 2.0$, which is how much A would be needed to use all the B — but the scientist only has $1.4$ L of A, so this is not achievable and represents returning an intermediate calculation. The value $2.60$ results from adding $1.4 + 1.2 = 2.6$, ignoring the ratio constraint entirely. The value $3.20$ results from incorrectly using all $1.2$ L of B and computing the total as $2.0 + 1.2 = 3.2$ without verifying that $2.0$ L of A is not available.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW212TWV3', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from Okamura''s study, if true, would most directly undermine the traditional explanation described in the text?', E'Geologists have traditionally attributed the unusually high concentration of iridium in the clay layer at the Cretaceous-Paleogene boundary to a single catastrophic asteroid impact approximately 66 million years ago. Geochemist Yuki Okamura, however, has proposed that sustained volcanic activity from the Deccan Traps in present-day India could have contributed a significant portion of the boundary iridium. Okamura does not deny that an asteroid impact occurred but argues that the traditional explanation oversimplifies the iridium signal by treating it as entirely extraterrestrial in origin.', $lyceon_json$[{"key":"A","text":"Iridium isotope ratios in several Deccan Traps basalt samples are indistinguishable from those found in the boundary clay layer at multiple sites worldwide."},{"key":"B","text":"The Chicxulub crater in Mexico, widely associated with the end-Cretaceous impact, dates to within 100,000 years of the boundary layer."},{"key":"C","text":"Other mass extinction events in Earth's history, such as the end-Permian event, have also been associated with large igneous provinces."},{"key":"D","text":"Computer models show that an asteroid of the estimated Chicxulub diameter could theoretically produce iridium concentrations exceeding those observed in the boundary layer."}]$lyceon_json$::jsonb, 'A', NULL, E'The traditional explanation holds that boundary iridium is entirely extraterrestrial. A finding that iridium isotope ratios in Deccan Traps basalt are indistinguishable from those in the boundary clay would directly undermine that explanation by demonstrating a plausible volcanic source with a matching geochemical signature. The finding about the Chicxulub crater''s dating supports the impact hypothesis rather than undermining it. The finding about other mass extinctions and igneous provinces establishes a general pattern but does not specifically challenge the iridium attribution at the K-Pg boundary. The finding about computer models showing the asteroid could produce sufficient iridium actually reinforces the traditional explanation rather than undermining it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23B2YTY', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief introduction to a presentation about monarch butterfly migration for classmates who are unfamiliar with the topic. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24RM1KW', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the passage, "tempered" most nearly means', E'The glassblower''s exuberance was tempered by years of meticulous training. Where once she had been impulsive, shaping molten glass with reckless energy, she now approached each piece with a deliberateness born of understanding how even a slight miscalculation could ruin hours of labor.', $lyceon_json$[{"key":"A","text":"moderated"},{"key":"B","text":"heated"},{"key":"C","text":"provoked"},{"key":"D","text":"abandoned"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how the glassblower''s exuberance was reduced or restrained by training, making "moderated" the correct choice. "Heated" relates to a different meaning of "temper" associated with metallurgy or glass treatment, not the sense used here. "Provoked" means stimulated or incited, which is the opposite of the restraining effect described. "Abandoned" goes too far — the passage says the exuberance was controlled, not eliminated entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25JT9O9', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the passages, Nakamura would most likely argue that Vásquez''s proposal is', E'Passage 1: Ecologist Rosa Vásquez proposes that reintroducing apex predators to degraded grassland ecosystems can trigger trophic cascades that restore native vegetation within a decade. She points to the reintroduction of wolves to a Montana valley in 2013, after which elk grazing pressure declined by forty-one percent and riparian willow coverage tripled by 2022. Vásquez argues that similar reintroductions should be prioritized across the North American Great Plains.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW264K8JQ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Restoration ecologist Tomás Heredia has argued that controlled burns in California''s mixed-conifer forests reduce wildfire severity by eliminating accumulated deadwood. His 2024 field data from the Plumas National Forest largely support this claim: plots that had undergone prescribed burns showed forty-seven percent less canopy loss during a subsequent wildfire than untreated plots. ________ Heredia cautions that prescribed burns conducted during drought conditions can inadvertently kill mature trees whose root systems are already water-stressed, potentially undermining the long-term resilience the burns are meant to promote.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"Moreover,"},{"key":"C","text":"Nevertheless,"},{"key":"D","text":"Consequently,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage first presents evidence supporting prescribed burns (reduced canopy loss), then introduces a cautionary qualification: burns during drought can harm the very trees they aim to protect. The correct transition signals a concession or complication that qualifies the preceding positive evidence. "Similarly" incorrectly signals a parallel finding, but the caution runs counter to the positive data. "Moreover" incorrectly signals an additional supporting point, yet the final sentence introduces a limitation rather than further support. "Consequently" incorrectly implies the caution is a direct result of the field data, when instead it is a separate complicating factor that Heredia raises alongside his supportive findings.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26TO7G8', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The evidence gathered from sediment layers at thirteen archaeological sites across the Yucatán Peninsula _______ that the region experienced prolonged droughts between 800 and 950 CE.', $lyceon_json$[{"key":"A","text":"suggest"},{"key":"B","text":"suggests"},{"key":"C","text":"are suggesting"},{"key":"D","text":"have suggested"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is ''evidence,'' which is a singular, uncountable noun. The prepositional phrase ''gathered from sediment layers at thirteen archaeological sites across the Yucatán Peninsula'' modifies ''evidence'' but does not change its number. A singular subject requires a singular verb form. The option ''suggests'' correctly pairs a singular present-tense verb with the singular subject ''evidence.'' The option ''suggest'' is a plural verb form that does not agree with the singular subject. The option ''are suggesting'' uses a plural auxiliary (''are'') that disagrees with the singular subject. The option ''have suggested'' uses a plural auxiliary (''have'') that also disagrees with the singular subject — the correct present-perfect form would require ''has suggested.''', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26WTYAH', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two passages?', E'Passage 1: Historian Anika Lindqvist contends that the decline of handwritten correspondence in the late twentieth century represented a genuine cultural loss. She argues that the physical act of writing by hand imposed a deliberative pace that encouraged nuanced emotional expression, and that typed communication, by enabling rapid composition, has flattened the emotional register of personal letters.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27G30K6', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary scholar, if accurate, would most effectively support the claim presented in the text?', E'Some historians of American literature argue that Zora Neale Hurston''s 1937 novel Their Eyes Were Watching God was largely dismissed by male critics of the Harlem Renaissance not because of its literary quality but because its focus on a Black woman''s interior emotional life conflicted with the prevailing expectation that African American fiction should primarily serve as social protest. This claim suggests that the novel''s critical reception was shaped more by ideological assumptions about the purpose of Black literature than by the work''s artistic merit.', $lyceon_json$[{"key":"A","text":"\"Hurston's prose style in Their Eyes Were Watching God draws heavily on the oral storytelling traditions of Eatonville, Florida, where she spent her formative years.\""},{"key":"B","text":"\"Richard Wright's 1937 review of Hurston's novel faulted it for lacking a political framework, revealing that his evaluative criteria prioritized social utility over narrative craft.\""},{"key":"C","text":"\"Their Eyes Were Watching God sold modestly upon publication, as did many novels released during the late 1930s economic downturn.\""},{"key":"D","text":"\"Hurston conducted extensive anthropological fieldwork in the Caribbean, which informed the folk elements present in several of her later works.\""}]$lyceon_json$::jsonb, 'B', NULL, E'The passage claims that male Harlem Renaissance critics dismissed Hurston''s novel because its subject matter did not align with their expectation that Black fiction should function as social protest. The quotation about Richard Wright faulting the novel for lacking a political framework directly illustrates this dynamic — a prominent male critic applying ideological rather than artistic criteria. The quotation about Hurston''s prose style and oral traditions discusses her literary influences but does not address the ideological basis of the novel''s critical reception. The quotation about modest sales attributes poor reception to economic conditions, which contradicts rather than supports the claim about ideological bias. The quotation about Caribbean fieldwork concerns later works and anthropological research, neither of which bears on the critical dismissal described in the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28CHNDR', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Of the forty-seven proposals submitted to the National Geothermal Research Initiative, the review panel determined that the one most likely to yield actionable results was the joint submission by Dr. Khánh Phan and _______ which outlined a novel method for mapping subsurface heat gradients using muon tomography.', $lyceon_json$[{"key":"A","text":"she,"},{"key":"B","text":"herself,"},{"key":"C","text":"hers,"},{"key":"D","text":"her,"}]$lyceon_json$::jsonb, 'D', NULL, E'The pronoun fills the second position in a compound object of the preposition ''by'': ''the joint submission by Dr. Khánh Phan and ___.'' Prepositions require the objective case for their objects. The objective-case pronoun ''her'' correctly completes the compound object of ''by.'' The subjective-case ''she'' is incorrect because the pronoun functions as the object of a preposition, not as a subject — a common hypercorrection error in compound constructions. The reflexive ''herself'' is incorrect because no antecedent in the sentence requires a reflexive pronoun; reflexive pronouns are used when the subject and object refer to the same person, which is not the case here. The possessive ''hers'' is incorrect because the sentence requires an object pronoun to complete the compound object of ''by,'' not a possessive form indicating ownership.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28FROZW', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing an essay arguing that deep-sea mining poses underappreciated ecological risks. The student wants to counter the claim that deep-sea ecosystems recover quickly from disturbance. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28KBGRW', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the main idea of the text?', E'Literary critic Renata Vasquez has reexamined the role of silence in the novels of Colombian author Álvaro Mutis. Previous scholarship interpreted Mutis''s frequent narrative gaps — passages where his protagonist Maqroll the Gaviero disappears from the text for months or years — as a modernist fragmentation technique indebted to European models. Vasquez contends, however, that these absences function differently from the disorienting lacunae of, say, Virginia Woolf or Samuel Beckett. In Mutis''s work, Vasquez argues, silence operates as a form of geographic testimony: Maqroll''s unnarrated intervals correspond to periods of itinerant labor in regions where colonial extraction has rendered lived experience illegible to metropolitan literary conventions. The gaps are not aesthetic disruptions but indices of structural unspeakability.', $lyceon_json$[{"key":"A","text":"Vasquez proposes that narrative gaps in Mutis's novels reflect the limits colonial conditions impose on representing certain experiences, rather than serving as a borrowed European modernist technique."},{"key":"B","text":"Vasquez demonstrates that Mutis intentionally modeled his narrative style on the fragmentation techniques of Woolf and Beckett but adapted them for a Latin American audience."},{"key":"C","text":"Vasquez's analysis reveals that Maqroll the Gaviero is an autobiographical figure whose disappearances from the text mirror periods in Mutis's own life."},{"key":"D","text":"Vasquez argues that silence in literature universally signals the failure of language to capture traumatic historical events."}]$lyceon_json$::jsonb, 'A', NULL, E'Vasquez''s central argument, as presented in the passage, is that the narrative gaps in Mutis''s novels are not European-style modernist fragmentation but rather a form of ''geographic testimony'' reflecting how colonial extraction has made certain experiences resistant to literary representation. The option linking narrative gaps to the limits colonial conditions impose on representation captures this precisely. The option about Mutis modeling his style on Woolf and Beckett contradicts Vasquez''s argument, which explicitly distinguishes Mutis''s silences from those European techniques. The option about Maqroll as autobiographical introduces a claim entirely absent from the text. The option about silence universally signaling failed language overgeneralizes Vasquez''s argument, which is specific to Mutis and colonial contexts.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AC71RC', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The review board recommended that the pharmaceutical company _______ its clinical trial protocols to include a broader demographic sample before proceeding with Phase III testing of the experimental antiviral compound designated MRX-4712.', $lyceon_json$[{"key":"A","text":"revise"},{"key":"B","text":"revises"},{"key":"C","text":"revised"},{"key":"D","text":"will revise"}]$lyceon_json$::jsonb, 'A', NULL, E'The verb ''recommended'' followed by ''that'' introduces a subjunctive clause. In Standard English, the subjunctive mood is required after verbs of recommendation, demand, suggestion, and insistence when followed by a ''that'' clause. The subjunctive uses the base form of the verb regardless of the subject''s number or person. The base form ''revise'' is correct in the subjunctive construction ''recommended that the pharmaceutical company revise.'' The option ''revises'' uses the indicative present tense with third-person singular agreement, but the subjunctive does not inflect for person or number. The option ''revised'' uses the past tense, which incorrectly shifts the time frame; the subjunctive base form is required regardless of when the recommendation was made. The option ''will revise'' introduces the future tense with a modal auxiliary, which is not grammatical in Standard English subjunctive constructions after ''recommended that.''', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BJPNE4', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the purpose of the passage?', E'Literary scholars have long debated whether the final chapter of Mikhail Borisov''s 1932 novel The Cartographer''s Dilemma was intended as satire or sincere tribute. Those who read it as satire point to the protagonist''s implausibly cheerful acceptance of his demotion, arguing that Borisov, himself demoted from an academic post that year, could not have meant the scene earnestly. Proponents of the sincere reading, however, note that Borisov''s personal correspondence from the period contains no trace of irony about professional setbacks; on the contrary, several letters express genuine relief at being freed from administrative duties. Neither camp, though, has reckoned with the possibility that the chapter functions simultaneously as both — a technique Borisov employed in at least three earlier works, where apparent contradictions in tone were deliberate rather than accidental.', $lyceon_json$[{"key":"A","text":"To present two competing interpretations of a literary work and suggest that both may be partially valid."},{"key":"B","text":"To argue definitively that a novelist's final chapter should be read as satire rather than tribute."},{"key":"C","text":"To provide biographical evidence that resolves a longstanding literary controversy."},{"key":"D","text":"To demonstrate that literary scholars consistently misread novels by overlooking authors' personal correspondence."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage lays out the satirical reading, then the sincere reading, and concludes by suggesting the chapter may function as both simultaneously — making the purpose to present two competing interpretations while indicating both may be partially valid. The option claiming the passage argues definitively for satire captures only the first interpretation and ignores the passage''s concluding synthesis. The option about biographical evidence resolving the controversy overstates the role of the letters — they are cited as support for one side, but the passage explicitly says the controversy remains unresolved. The option about scholars consistently misreading novels by ignoring correspondence mischaracterizes the passage''s scope, which addresses one specific debate about one novel rather than making a sweeping claim about scholarly methods.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CHNAK5', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'Ethnomusicologist Tomoko Fujiwara has challenged the prevailing assumption that the gagaku tradition of Japanese court music remained essentially unchanged for over a millennium. By analyzing notation manuscripts from the Heian period (794–1185 CE) alongside recordings of modern gagaku ensembles, Fujiwara identified systematic shifts in tempo, ornamentation patterns, and tuning systems. For instance, the modal framework known as ryo, which contemporary performers treat as a fixed scale, appears in eleventh-century manuscripts with microtonal inflections absent from today''s practice. Fujiwara argues that what performers now regard as ancient authenticity is itself a product of nineteenth-century standardization efforts during the Meiji Restoration.', $lyceon_json$[{"key":"A","text":"Research comparing historical and modern sources indicates that gagaku has undergone more transformation than is commonly recognized."},{"key":"B","text":"The ryo modal framework used in gagaku has been replaced by an entirely different tuning system since the Heian period."},{"key":"C","text":"Gagaku's reputation as an unchanged tradition has led modern performers to reject all forms of musical innovation."},{"key":"D","text":"Fujiwara's primary contribution is the discovery of previously unknown Heian-period notation manuscripts."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Fujiwara''s challenge to the idea that gagaku remained unchanged, supporting this with evidence of shifts in tempo, ornamentation, and tuning. The option about research comparing historical and modern sources revealing more transformation than commonly recognized captures this central argument. The option claiming the ryo framework has been entirely replaced overstates the finding — Fujiwara notes the loss of microtonal inflections, not a wholesale replacement. The option about performers rejecting all innovation goes beyond anything stated in the text. The option crediting Fujiwara with discovering unknown manuscripts misrepresents her work; she analyzed existing manuscripts, and the passage does not describe them as previously unknown.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CUCC0O', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Ecologists at the University of São Paulo hypothesize that the rapid decline of the golden-headed lion tamarin (Leontopithecus chrysomelas) in southeastern Bahia is driven primarily by the fragmentation of Atlantic Forest habitat into small, isolated patches rather than by direct predation or disease. According to this hypothesis, tamarins in smaller forest fragments experience reduced genetic diversity and limited access to fruiting trees, which together lower reproductive success.', $lyceon_json$[{"key":"A","text":"Tamarin populations in large, continuous forest reserves show significantly higher birth rates and greater genetic variation than populations in fragments smaller than fifty hectares."},{"key":"B","text":"The golden-headed lion tamarin's diet consists of over forty species of fruit-bearing plants found throughout the Atlantic Forest biome."},{"key":"C","text":"Predation rates on tamarins by raptors are roughly equal in fragmented and continuous forest areas."},{"key":"D","text":"Tamarin populations in small forest fragments have developed novel foraging strategies not observed in continuous forest populations."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis holds that habitat fragmentation reduces genetic diversity and access to fruiting trees, thereby lowering reproductive success. A finding that tamarin populations in large continuous reserves have higher birth rates and greater genetic variation than those in small fragments would directly confirm the predicted link between fragment size, genetic diversity, and reproduction. The option about the tamarin''s diet lists dietary breadth but does not compare outcomes across fragment sizes, so it does not address the hypothesis''s mechanism. The option about equal predation rates is relevant to ruling out an alternative explanation but does not directly support the fragmentation-reproduction link the hypothesis proposes. The option about novel foraging strategies describes behavioral adaptation but does not bear on genetic diversity or reproductive success.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DFN6SZ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologists at the Farallon Islands research station have documented a steep decline in the local population of Cassin''s auklets over the past eleven years. ________ the researchers have proposed restricting commercial fishing vessels from operating within a nineteen-kilometer radius of the islands during the auklets'' nesting season.', $lyceon_json$[{"key":"A","text":"In response,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"Granted,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a problem (a steep decline in the auklet population) and then presents a proposed action (restricting fishing vessels). The correct transition signals that the proposal is a reaction to the documented decline. "In contrast" incorrectly signals opposition between two ideas that are causally linked, not opposing. "Granted" incorrectly signals a concession, but the second sentence is not conceding a point. "Specifically" incorrectly signals elaboration of the same idea, but the second sentence introduces a new action rather than adding detail to the decline.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E1VRC5', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'In a 2023 study, archaeologist Priya Venkatesh analyzed carbon isotope ratios in cattle bones unearthed at a Bronze Age settlement near the Tigris River. Her findings indicated that the cattle had been fed cultivated barley rather than wild grasses, suggesting the settlement''s inhabitants practiced organized animal husbandry. ________ isotope data from goat remains at the same site showed a diet consisting almost entirely of uncultivated vegetation, indicating that goats were left to forage freely.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"However,"},{"key":"C","text":"As a result,"},{"key":"D","text":"In other words,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage establishes that cattle were fed cultivated barley, suggesting organized husbandry, but then notes that goats ate uncultivated vegetation and foraged freely — a contrasting finding about animal management at the same site. The correct transition signals this contrast. "Furthermore" incorrectly signals that the goat data adds supporting evidence in the same direction, when it actually contradicts the organized husbandry pattern. "As a result" incorrectly implies the goat data is a consequence of the cattle findings. "In other words" incorrectly suggests the goat data restates the cattle findings, when the two findings diverge.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F159GT', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'After botanist Miriam Osei-Bonsu discovered a high concentration of alkaloids in the bark of the West African plant Alstonia boonei in 2019, she _______ a series of extraction experiments that ultimately yielded three compounds with potential antimalarial properties.', $lyceon_json$[{"key":"A","text":"initiates"},{"key":"B","text":"has initiated"},{"key":"C","text":"initiated"},{"key":"D","text":"would initiate"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage establishes a past time frame through the subordinate clause beginning with ''After,'' the past-tense verb ''discovered,'' and the specific year ''2019.'' The main clause must maintain tense consistency with this established past narrative. The simple past ''initiated'' correctly matches the past time frame and indicates a completed action that followed the discovery. The present-tense ''initiates'' breaks tense consistency by shifting to the present within a past narrative. The present-perfect ''has initiated'' is incorrect because the present perfect connects past actions to the present, but the specific past time marker ''2019'' and the completed-action context (''ultimately yielded'') require simple past. The conditional ''would initiate'' incorrectly implies a hypothetical or habitual action rather than reporting a factual sequence of events.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FLCPMC', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Art historian Celeste Moreau has examined the economic records of seventeenth-century Dutch flower painters to complicate the widespread belief that their still-life compositions were primarily vanitas allegories — symbolic reminders of life''s transience. Moreau found that painters such as Rachel Ruysch and Jan van Huysum routinely corresponded with botanical collectors and nursery owners, adjusting their compositions to feature newly imported cultivars that commanded high market prices. Invoices show that patrons frequently specified which rare specimens should appear in commissioned works, and that painters charged premium rates for canvases depicting high-value tulip varieties. Moreau argues that while the vanitas reading is not entirely unfounded, these economic records suggest that flower paintings also functioned as ________', $lyceon_json$[{"key":"A","text":"visual inventories of collectible botanical commodities that signaled their owners' participation in the horticultural luxury market."},{"key":"B","text":"scientifically precise botanical illustrations intended to replace the hand-drawn plates in published horticultural reference guides."},{"key":"C","text":"covert political commentaries criticizing the Dutch Republic's speculative trading practices during the tulip mania period."},{"key":"D","text":"pedagogical tools designed to teach amateur gardeners how to cultivate rare flower species in domestic settings."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that painters adjusted compositions for newly imported high-value cultivars, that patrons specified rare specimens, and that premium rates were charged for high-value varieties. These details collectively point to flower paintings functioning as displays of botanical commodities that marked owners'' status in the luxury horticultural market. The option about scientifically precise botanical illustrations oversteps — the passage describes commercial correspondence and patron commissions, not scientific illustration projects or published reference guides. The option about covert political commentary on speculative trading introduces a critical dimension entirely absent from the economic evidence Moreau cites. The option about pedagogical tools for amateur gardeners attributes an instructional purpose that nothing in the passage supports; the evidence points to display and prestige, not horticultural education.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H1O90T', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'While most computational models of early Sumerian cuneiform treat each logogram as a discrete semantic unit, epigrapher Nahla al-Rashid has demonstrated that certain sequences of logograms function as phonetic complements rather than as independent _______ this finding has prompted researchers to reconsider whether the writing system encoded phonetic information earlier than previously believed.', $lyceon_json$[{"key":"A","text":"words; for example,"},{"key":"B","text":"words,"},{"key":"C","text":"words; instead,"},{"key":"D","text":"words, and"}]$lyceon_json$::jsonb, 'D', NULL, E'The passage consists of two independent clauses. The first clause (beginning with the subordinate ''While'' clause and continuing through ''independent words'') presents al-Rashid''s finding. The second clause describes the consequence of that finding. A comma followed by the coordinating conjunction ''and'' correctly joins these two independent clauses, which have an additive-consequential relationship. The option using ''for example'' after a semicolon is logically wrong because the second clause does not illustrate or exemplify the first — it describes a broader impact of the finding rather than providing a specific instance. The option with only a comma creates a comma splice between the two independent clauses. The option using ''instead'' after a semicolon incorrectly signals substitution or replacement; the second clause does not replace the first but rather extends it by describing its impact on the research community.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ILP6LC', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Linguist Amara Osei''s analysis of seventeenth-century Akan trade pidgins reveals that these contact languages incorporated Portuguese loanwords for commercial goods such as textiles and firearms but relied on Akan-derived terms for kinship, spiritual practices, and governance. Osei interprets this pattern as evidence that Akan communities selectively adopted foreign vocabulary only where it served transactional purposes, preserving indigenous terminology in domains central to social identity. ________ historian Kweku Mensah has pointed out that many of the supposedly Portuguese-origin trade terms actually entered Akan languages through Mande intermediaries who had contact with Lusophone traders a century earlier, complicating Osei''s direct-borrowing model.', $lyceon_json$[{"key":"A","text":"That said,"},{"key":"B","text":"By the same token,"},{"key":"C","text":"To illustrate,"},{"key":"D","text":"Indeed,"}]$lyceon_json$::jsonb, 'A', NULL, E'Osei''s interpretation is presented as a coherent claim about selective vocabulary adoption. Mensah''s response complicates that interpretation by introducing an alternative transmission route, which does not flatly refute Osei but qualifies the directness of the borrowing model. The correct transition signals a counter-consideration or qualification introduced after an established position. "By the same token" incorrectly signals that Mensah''s point extends Osei''s reasoning in a parallel direction, when it actually challenges part of her model. "To illustrate" incorrectly signals that Mensah is providing an example supporting Osei''s claim, but his point undermines one of its premises. "Indeed" incorrectly signals emphatic agreement with or reinforcement of Osei''s interpretation, whereas Mensah''s observation complicates it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JGUMSD', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Marine biologist Anika Patel has documented an unusual feeding behavior among mantis shrimp in the Andaman Sea. Unlike most crustaceans that scavenge for food along the ocean floor, the peacock mantis shrimp (Odontodactylus scyllarus) actively hunts gastropods by delivering rapid strikes with its specialized appendages. Patel''s 2023 field observations confirmed that these strikes generate forces exceeding 1,500 newtons — sufficient to shatter the shells of even thick-shelled prey. Her findings suggest that the mantis shrimp''s hunting strategy is among the most mechanically powerful in the marine invertebrate world.', $lyceon_json$[{"key":"A","text":"Mantis shrimp in the Andaman Sea face increasing competition from other predators for gastropod prey."},{"key":"B","text":"Research has shown that the peacock mantis shrimp uses an exceptionally powerful hunting method to capture shelled prey."},{"key":"C","text":"Anika Patel's work focuses primarily on comparing the feeding behaviors of different crustacean species."},{"key":"D","text":"The peacock mantis shrimp is the only crustacean species known to hunt rather than scavenge for food."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage centers on Patel''s documentation of the mantis shrimp''s powerful hunting strikes, which exceed 1,500 newtons and can shatter gastropod shells. The option stating that research has shown the peacock mantis shrimp uses an exceptionally powerful hunting method to capture shelled prey accurately captures this central point. The option about competition from other predators introduces a claim not present in the text. The option about comparing feeding behaviors of different crustacean species overstates the comparative element — the passage mentions other crustaceans only briefly to contrast scavenging with active hunting. The option claiming the mantis shrimp is the only crustacean that hunts goes beyond the text, which says ''unlike most crustaceans,'' not ''unlike all.''', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KQWBJY', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the passage, "plastic" most nearly means', E'Contrary to the popular notion that adult brains are fixed in their architecture, recent longitudinal studies of bilingual individuals suggest that neural pathways remain remarkably plastic well into the seventh decade of life. Participants who began learning a third language after age fifty-five showed measurable increases in cortical thickness within fourteen months.', $lyceon_json$[{"key":"A","text":"adaptable"},{"key":"B","text":"synthetic"},{"key":"C","text":"rigid"},{"key":"D","text":"transparent"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage contrasts the idea that adult brains are "fixed" with evidence that neural pathways can change, making "adaptable" the correct meaning. "Synthetic" refers to the material sense of "plastic" — an artificial substance — which is irrelevant to the biological context. "Rigid" means stiff and unyielding, the direct opposite of the malleability described. "Transparent" means see-through or easily understood, which has no connection to the passage''s discussion of neural change.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KZ7KP2', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Ceramic artist Tomoko Fujiwara creates large-scale installations using reclaimed industrial _______ her sculptures have been exhibited in nineteen galleries across East Asia.', $lyceon_json$[{"key":"A","text":"clay; for instance,"},{"key":"B","text":"clay, and"},{"key":"C","text":"clay,"},{"key":"D","text":"clay; in contrast,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage contains two independent clauses: one about Fujiwara creating installations and one about her sculptures being exhibited. These clauses have an additive relationship — the second clause provides additional information about the artist''s accomplishments. A comma followed by the coordinating conjunction ''and'' correctly joins two independent clauses with an additive relationship. The option using a semicolon with ''for instance'' is wrong because the second clause is not an example of the first — it introduces a separate fact rather than illustrating the preceding claim. The option with only a comma creates a comma splice, which is a sentence boundary error. The option using a semicolon with ''in contrast'' incorrectly signals opposition between two clauses that are complementary, not contrasting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NGX5M4', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the passage, "economy" most nearly means', E'The poet Yusuf al-Khatib was celebrated for the economy of his verse. In a 1971 collection spanning forty-three poems, no single piece exceeded eleven lines, yet critics noted that each contained enough layered allusion to sustain a seminar-length discussion. Al-Khatib himself remarked that he revised each poem at least thirty times, pruning until every syllable bore weight.', $lyceon_json$[{"key":"A","text":"brevity"},{"key":"B","text":"prosperity"},{"key":"C","text":"commerce"},{"key":"D","text":"thriftiness"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a poet whose works are extremely short yet dense, and who revises extensively to eliminate excess. This describes brevity — concise, efficient expression. "Prosperity" relates to financial wealth, a meaning of "economy" that has no bearing on poetic style. "Commerce" refers to trade and business activity, another financial sense irrelevant to verse composition. "Thriftiness" means frugality with money or resources; while superficially related to the idea of using less, it denotes a financial habit rather than the deliberate conciseness of artistic expression, and substituting it into the sentence produces an incoherent meaning — one is not celebrated for the frugality of verse.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OM5GHT', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In a 2023 analysis of municipal water usage in nine landlocked counties in eastern Montana, hydrologist Elara Kittredge determined that aquifer levels had declined by twenty-three percent over the preceding _______ she also found that seasonal replenishment rates had slowed by nearly a third during the same period.', $lyceon_json$[{"key":"A","text":"decade, and"},{"key":"B","text":"decade; nonetheless,"},{"key":"C","text":"decade,"},{"key":"D","text":"decade; on the other hand,"}]$lyceon_json$::jsonb, 'A', NULL, E'Two independent clauses describe parallel findings from the same study: declining aquifer levels and slowing replenishment rates. The word ''also'' in the second clause signals that these findings are additive and complementary. A comma followed by the coordinating conjunction ''and'' correctly joins two independent clauses in an additive relationship, which is consistent with ''also.'' The option using ''nonetheless'' incorrectly implies that the second finding is surprising given the first, but slower replenishment is consistent with — not contrary to — declining aquifer levels. The option with only a comma creates a comma splice between the two independent clauses. The option using ''on the other hand'' incorrectly signals contrast, but both findings point in the same direction: worsening water conditions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QG1XFL', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Urban planner Deshawn Holloway studied pedestrian traffic patterns in eleven mid-sized U.S. cities between 2019 and 2023. In cities that converted downtown streets to pedestrian-only zones, foot traffic increased by an average of 37 percent within the first eighteen months. Retail vacancy rates in these zones dropped by 14 percent over the same period, while adjacent streets with vehicle access saw no statistically significant change in vacancy. Holloway concluded that pedestrian-only conversions ________', $lyceon_json$[{"key":"A","text":"tend to boost commercial activity within the converted areas without significantly harming businesses on nearby streets."},{"key":"B","text":"are most effective when implemented alongside reductions in public transit service to surrounding neighborhoods."},{"key":"C","text":"succeed primarily because they attract national retail chains that had previously avoided downtown locations."},{"key":"D","text":"consistently reduce vehicle congestion throughout the entire metropolitan area of the cities studied."}]$lyceon_json$::jsonb, 'A', NULL, E'The data show that pedestrian zones saw increased foot traffic and decreased retail vacancy, while adjacent vehicle-access streets experienced no significant change. The conclusion that conversions boost commercial activity in the converted areas without significantly harming nearby businesses follows directly from these findings. The option about reducing public transit introduces a claim unsupported by and unrelated to the data presented. The option about attracting national retail chains specifies a mechanism the passage never mentions. The option about reducing vehicle congestion throughout the metropolitan area goes far beyond the scope of the study, which measured pedestrian traffic and retail vacancy, not citywide vehicle congestion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QYNMHO', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the passages, how would the author of Passage 2 most likely respond to the claim made in Passage 1?', E'Passage 1: Urban planner Mireille Desrosiers argues that converting vacant commercial lots into community gardens yields measurable public health benefits. A 2021 study she cites found that neighborhoods with at least one community garden per four blocks reported seventeen percent fewer emergency room visits for stress-related conditions compared to similar neighborhoods without gardens.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TOPCAK', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Geochemist Lucía Monteagudo, who has analyzed sediment cores from eleven volcanic lakes in Patagonia, published her findings in the journal Quaternary _______ the study revealed that volcanic ash deposits from 1,340 years ago contained unusually high concentrations of iridium.', $lyceon_json$[{"key":"A","text":"Research,"},{"key":"B","text":"Research; nevertheless,"},{"key":"C","text":"Research, and"},{"key":"D","text":"Research; rather,"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence contains two independent clauses separated by the blank: the first describes Monteagudo publishing her findings, and the second describes what the study revealed. The non-restrictive clause ''who has analyzed sediment cores from eleven volcanic lakes in Patagonia'' is set off by commas and modifies ''Lucía Monteagudo'' — it does not change the grammatical structure of the main clauses. A comma followed by the coordinating conjunction ''and'' correctly joins the two independent clauses, which share an additive relationship. The option with only a comma after ''Research'' creates a comma splice between two independent clauses. The option using ''nevertheless'' incorrectly implies concession or contrast between publishing findings and what those findings revealed — no opposition exists between these clauses. The option using ''rather'' incorrectly signals correction or substitution, as though the second clause replaces the first, which does not fit the logical relationship.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UIP1JX', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Neuroscientist Priya Chandrasekaran investigated whether bilingual adults process numerical information differently depending on the language in which they learned arithmetic. She administered timed calculation tasks to forty-three Kannada-English bilingual participants, all of whom had learned basic arithmetic exclusively in Kannada-medium schools before acquiring English fluency in secondary school. Participants solved multiplication problems significantly faster when the problems were presented in Kannada script than when identical problems appeared in English, even though all participants reported using English as their dominant professional language for over a decade. Chandrasekaran suggested that these results indicate ________', $lyceon_json$[{"key":"A","text":"that early arithmetic training creates language-specific mental representations for calculation that persist despite prolonged dominance of a second language."},{"key":"B","text":"that bilingual individuals are generally slower at mathematical reasoning than monolingual individuals regardless of the language used."},{"key":"C","text":"that Kannada script is inherently more efficient for representing numerical operations than English script."},{"key":"D","text":"that participants' self-reports of English as their dominant professional language were inaccurate."}]$lyceon_json$::jsonb, 'A', NULL, E'The study found that bilingual participants solved arithmetic problems faster in the language of their early arithmetic education, even after a decade of professional dominance in a second language. The inference that early arithmetic training creates persistent language-specific mental representations follows logically from these results. The option about bilinguals being generally slower than monolinguals introduces a comparison the study never made — it compared performance within the same bilingual individuals across languages. The option claiming Kannada script is inherently more efficient attributes the effect to the script itself rather than to the participants'' learning history, which the study design cannot support. The option suggesting participants'' self-reports were inaccurate contradicts the study''s framing without evidence and would undermine the finding rather than explain it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YXAET0', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the passage?', E'Coral reefs occupy less than one percent of the ocean floor, yet they support roughly a quarter of all marine species. [underlined] Marine biologists sometimes call reefs "the rainforests of the sea" because of this extraordinary concentration of biodiversity. [/underlined] Research teams cataloging species on a single Philippine reef system in 2019 documented over 2,700 distinct organisms within an area smaller than a municipal park.', $lyceon_json$[{"key":"A","text":"It provides an analogy that reinforces the claim made in the preceding sentence."},{"key":"B","text":"It introduces a counterargument to the passage's central thesis."},{"key":"C","text":"It presents quantitative evidence supporting a researcher's hypothesis."},{"key":"D","text":"It shifts the passage's focus from marine biology to forestry."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence draws a comparison between reefs and rainforests to emphasize the biodiversity claim made in the first sentence, so it provides an analogy reinforcing that claim. The option suggesting a counterargument is wrong because the underlined sentence supports rather than challenges the opening assertion. The option claiming quantitative evidence is incorrect because the analogy contains no numbers — the quantitative data appears in the following sentence instead. The option about shifting focus to forestry misreads the metaphor: "rainforests of the sea" is a figurative comparison, not a literal change of subject.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z4QLJP', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the passage?', E'In 1847, the Hungarian physician Ignaz Semmelweis observed that maternity ward mortality rates dropped from twelve percent to under two percent when doctors washed their hands in a chlorinated lime solution before examining patients. Despite this dramatic evidence, the medical establishment largely dismissed his findings. Prominent surgeons argued that a gentleman''s hands could not carry disease, and journal editors refused to publish his data. It was not until two decades later, after Louis Pasteur''s germ theory provided a mechanistic explanation, that hand hygiene became standard practice.', $lyceon_json$[{"key":"A","text":"It presents a discovery, describes resistance to that discovery, and explains how the discovery was eventually accepted."},{"key":"B","text":"It compares the medical contributions of two researchers and argues that one was more important than the other."},{"key":"C","text":"It describes a medical controversy and then evaluates the experimental methods used by both sides."},{"key":"D","text":"It introduces a hypothesis, provides evidence disproving it, and proposes an alternative explanation."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage follows a three-part arc: Semmelweis''s observation (discovery), the medical establishment''s rejection (resistance), and eventual acceptance after Pasteur''s germ theory (resolution). The option about comparing two researchers'' contributions distorts the passage''s purpose — Pasteur is mentioned only as the catalyst for acceptance, not as a rival whose work is ranked. The option about evaluating experimental methods on both sides is wrong because the passage never discusses the methodology of those who opposed Semmelweis. The option about introducing and disproving a hypothesis reverses the passage''s logic — Semmelweis''s finding was ultimately confirmed, not disproved.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z79TQJ', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a research summary and wants to emphasize a difference between two approaches to reducing urban heat islands. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
